<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/_crm.php';
$cid=crm_company_id();$err='';$ok='';$editStatus=max(0,(int)($_GET['edit_status']??0));$editType=max(0,(int)($_GET['edit_type']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{crm_csrf_check((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
    if($action==='save_status'){$id=max(0,(int)($_POST['id']??0));$name=trim((string)($_POST['name']??''));$color=crm_clean_color((string)($_POST['color']??''));$sort=(int)($_POST['sort_order']??0);if($name==='')throw new RuntimeException('Informe o nome do status.');if($id>0){$st=$pdo->prepare('UPDATE crm_statuses SET name=?,color=?,sort_order=?,updated_at=NOW() WHERE company_id=? AND id=?');$st->execute([$name,$color,$sort,$cid,$id]);}else{$st=$pdo->prepare('INSERT INTO crm_statuses(company_id,name,color,active,sort_order,created_at) VALUES(?,?,?,1,?,NOW())');$st->execute([$cid,$name,$color,$sort]);}$ok='Status salvo.';}
    elseif($action==='toggle_status'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('UPDATE crm_statuses SET active=IF(active=1,0,1),updated_at=NOW() WHERE company_id=? AND id=?')->execute([$cid,$id]);$ok='Status atualizado.';}
    elseif($action==='save_type'){$id=max(0,(int)($_POST['id']??0));$name=trim((string)($_POST['name']??''));$sort=(int)($_POST['sort_order']??0);if($name==='')throw new RuntimeException('Informe o nome do tipo de atendimento.');if($id>0){$pdo->prepare('UPDATE crm_service_types SET name=?,sort_order=?,updated_at=NOW() WHERE company_id=? AND id=?')->execute([$name,$sort,$cid,$id]);}else{$pdo->prepare('INSERT INTO crm_service_types(company_id,name,active,sort_order,created_at) VALUES(?,?,1,?,NOW())')->execute([$cid,$name,$sort]);}$ok='Tipo de atendimento salvo.';}
    elseif($action==='toggle_type'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('UPDATE crm_service_types SET active=IF(active=1,0,1),updated_at=NOW() WHERE company_id=? AND id=?')->execute([$cid,$id]);$ok='Tipo atualizado.';}
    else throw new RuntimeException('Ação inválida.');
  }catch(Throwable $e){$err=$e->getMessage();}
}
$statuses=crm_statuses($pdo,$cid,false);$types=crm_types($pdo,$cid,false);$sEdit=[];$tEdit=[];foreach($statuses as $s)if((int)$s['id']===$editStatus)$sEdit=$s;foreach($types as $t)if((int)$t['id']===$editType)$tEdit=$t;
crm_page_start('CRM - Status, Tipos e Mensagens','crm_atendimentos');
?>
