<div class="crm-form-grid">
<div class="crm-card crm-span2"><div class="crm-card-head">Status do atendimento</div><div class="crm-card-body"><form method="post" class="crm-form-grid"><input type="hidden" name="csrf" value="<?=crm_e(crm_csrf_token())?>"><input type="hidden" name="action" value="save_status"><input type="hidden" name="id" value="<?=(int)($sEdit['id']??0)?>"><div class="crm-field crm-span2"><label>Nome</label><input name="name" required value="<?=crm_e($sEdit['name']??'')?>"></div><div class="crm-field"><label>Cor</label><input type="color" name="color" value="<?=crm_e(crm_clean_color((string)($sEdit['color']??'#2563EB')))?>" style="height:42px;padding:4px"></div><div class="crm-field"><label>Ordem</label><input type="number" name="sort_order" value="<?=crm_e($sEdit['sort_order']??0)?>"></div><div class="crm-span2 crm-actions"><button class="crm-btn primary">Salvar status</button><?php if($sEdit):?><a class="crm-btn" href="crm_configuracoes.php">Cancelar edição</a><?php endif;?></div></form><div style="height:12px"></div><div class="crm-advanced-wrap"><table class="crm-data-grid" style="table-layout:auto"><thead><tr><th>Cor</th><th>Status</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($statuses as $s):$c=crm_clean_color((string)$s['color']);?><tr><td><span class="crm-status-dot" style="background:<?=crm_e($c)?>"></span><?=crm_e($c)?></td><td><strong><?=crm_e($s['name'])?></strong></td><td><?=!empty($s['active'])?'Ativo':'Inativo'?></td><td><div class="crm-actions"><a class="crm-btn sm" href="crm_configuracoes.php?edit_status=<?=(int)$s['id']?>">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?=crm_e(crm_csrf_token())?>"><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="crm-btn sm"><?=!empty($s['active'])?'Inativar':'Ativar'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="crm-card crm-span2"><div class="crm-card-head">Tipos de atendimento</div><div class="crm-card-body"><form method="post" class="crm-form-grid"><input type="hidden" name="csrf" value="<?=crm_e(crm_csrf_token())?>"><input type="hidden" name="action" value="save_type"><input type="hidden" name="id" value="<?=(int)($tEdit['id']??0)?>"><div class="crm-field crm-span2"><label>Nome</label><input name="name" required value="<?=crm_e($tEdit['name']??'')?>"></div><div class="crm-field"><label>Ordem</label><input type="number" name="sort_order" value="<?=crm_e($tEdit['sort_order']??0)?>"></div><div class="crm-span2 crm-actions"><button class="crm-btn primary">Salvar tipo</button><?php if($tEdit):?><a class="crm-btn" href="crm_configuracoes.php">Cancelar edição</a><?php endif;?></div></form><div style="height:12px"></div><div class="crm-advanced-wrap"><table class="crm-data-grid" style="table-layout:auto"><thead><tr><th>Tipo</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($types as $t):?><tr><td><strong><?=crm_e($t['name'])?></strong></td><td><?=!empty($t['active'])?'Ativo':'Inativo'?></td><td><div class="crm-actions"><a class="crm-btn sm" href="crm_configuracoes.php?edit_type=<?=(int)$t['id']?>">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?=crm_e(crm_csrf_token())?>"><input type="hidden" name="action" value="toggle_type"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button class="crm-btn sm"><?=!empty($t['active'])?'Inativar':'Ativar'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
</div>
